package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items
var WsEofFlag string = "N"   // PIC X len=1
var WsFirstFlag string = "Y" // PIC X len=1
var WsPrevDept string = "   " // PIC X(3) len=3
var WsRegHours decimal.Decimal = decimal.NewFromInt(0)   // PIC 9(3)V9
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)    // PIC 9(3)V9
var WsGross decimal.Decimal = decimal.NewFromInt(0)      // PIC 9(7)V99
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0)  // PIC 9(9)V99
var WsDeptCount int64 = 0                                // PIC 9(3)
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(11)V99
var WsGrandCount int64 = 0                               // PIC 9(5)
var WsHoursEd string // PIC ZZ9.9 len=5
var WsRateEd string  // PIC ZZ9.99 len=6
var WsGrossEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string  // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var EmpRecData EmpRec
var empLines []string
var empIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func isFirstRecord() bool {
	return WsFirstFlag == "Y"
}

func parseDisplay(s string, scale int32) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -scale)
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	scaled := t.Shift(scale).IntPart()
	totalDigits := intDigits + int(scale)
	mod := int64(1)
	for i := 0; i < totalDigits; i++ {
		mod *= 10
	}
	r := scaled % mod
	return decimal.New(r, -scale)
}

func formatEdited(v decimal.Decimal, intSlots int, fracScale int, pic string) string {
	t := v.Truncate(int32(fracScale))
	absScaled := t.Abs().Shift(int32(fracScale)).IntPart()
	powF := int64(1)
	for i := 0; i < fracScale; i++ {
		powF *= 10
	}
	powN := int64(1)
	for i := 0; i < intSlots; i++ {
		powN *= 10
	}
	var intFull, fracPart int64
	if fracScale == 0 {
		intFull = absScaled
		fracPart = 0
	} else {
		intFull = absScaled / powF
		fracPart = absScaled % powF
	}
	intMod := intFull % powN
	intStr := fmt.Sprintf("%0*d", intSlots, intMod)
	fracStr := ""
	if fracScale > 0 {
		fracStr = fmt.Sprintf("%0*d", fracScale, fracPart)
	}
	dotIdx := strings.Index(pic, ".")
	var intPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
	} else {
		intPic = pic
	}
	var sb strings.Builder
	di := 0
	suppressed := true
	for _, ch := range intPic {
		if ch == ',' {
			if suppressed {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		} else if ch == 'Z' || ch == '9' {
			d := intStr[di]
			di++
			if ch == 'Z' && suppressed && d == '0' {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(d)
				suppressed = false
			}
		} else {
			sb.WriteRune(ch)
		}
	}
	if dotIdx >= 0 {
		sb.WriteByte('.')
		sb.WriteString(fracStr)
	}
	return sb.String()
}

func openEmpFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			empLines = nil
			empIdx = 0
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	s := string(data)
	if s == "" {
		empLines = nil
		empIdx = 0
		return
	}
	parts := strings.Split(s, "\n")
	if strings.HasSuffix(s, "\n") {
		parts = parts[:len(parts)-1]
	}
	empLines = make([]string, 0, len(parts))
	for _, p := range parts {
		if strings.HasSuffix(p, "\r") {
			p = p[:len(p)-1]
		}
		empLines = append(empLines, p)
	}
	empIdx = 0
}

func MainPara() {
	openEmpFile()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		DeptBreakPara()
	}
	GrandPara()
}

func ReadPara() {
	if empIdx >= len(empLines) {
		WsEofFlag = "Y"
		return
	}
	line := empLines[empIdx]
	empIdx++
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	EmpRecData.ErId = line[0:5]
	EmpRecData.ErDept = line[5:8]
	hoursStr := line[8:12]
	rateStr := line[12:17]
	EmpRecData.ErHours = parseDisplay(hoursStr, 1)
	EmpRecData.ErRate = parseDisplay(rateStr, 2)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = EmpRecData.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecData.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = EmpRecData.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	if EmpRecData.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = storeDecimal(decimal.NewFromInt(40), 3, 1)
		diff := EmpRecData.ErHours.Sub(decimal.NewFromInt(40))
		WsOtHours = storeDecimal(diff, 3, 1)
	} else {
		WsRegHours = storeDecimal(EmpRecData.ErHours, 3, 1)
		WsOtHours = storeDecimal(decimal.NewFromInt(0), 3, 1)
	}
	onePointFive := decimal.New(15, -1)
	term1 := WsRegHours.Mul(EmpRecData.ErRate)
	term2 := WsOtHours.Mul(EmpRecData.ErRate).Mul(onePointFive)
	sum := term1.Add(term2)
	rounded := sum.Round(2)
	WsGross = storeDecimal(rounded, 7, 2)
	WsDeptTotal = storeDecimal(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = (WsDeptCount + 1) % 1000
	WsGrandTotal = storeDecimal(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = (WsGrandCount + 1) % 100000
	WsHoursEd = formatEdited(EmpRecData.ErHours, 3, 1, "ZZ9.9")
	WsRateEd = formatEdited(EmpRecData.ErRate, 3, 2, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, 7, 2, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", EmpRecData.ErId, EmpRecData.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, 9, 2, "ZZZ,ZZZ,ZZ9.99")
	deptCountStr := fmt.Sprintf("%03d", WsDeptCount)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, deptCountStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, 11, 2, "ZZ,ZZZ,ZZZ,ZZ9.99")
	grandCountStr := fmt.Sprintf("%05d", WsGrandCount)
	fmt.Printf("GRAND TOTAL (%s): %s\n", grandCountStr, WsGrandEd)
}

func main() {
	MainPara()
}
